import { DataSource } from 'typeorm';

export interface CreateUsageHeartbeatInput {
  [key: string]: unknown;
}

export async function createTestUsageHeartbeat(
  dataSource: DataSource,
  overrides: CreateUsageHeartbeatInput = {},
): Promise<Record<string, unknown>> {
  const meta = dataSource.entityMetadatas.find(
    (m) => m.name === 'UsageHeartbeat' || m.tableName === 'usage_heartbeat',
  );
  if (!meta) {
    throw new Error('createTestUsageHeartbeat: UsageHeartbeat entity not registered with the DataSource');
  }
  const repo = dataSource.getRepository(meta.target);
  const row: Record<string, unknown> = {
    timestamp: new Date(),
    minutes: 0,
    ...overrides,
  };
  const saved = await repo.save(row as never);
  return saved as unknown as Record<string, unknown>;
}
